import 'package:auto_shop_server/app/utils/global.dart';import 'package:flutter/material.dart';class NumberCount extends StatefulWidget {  final String? title;  final Widget? rightView;  final Function(dynamic) onChange;  const NumberCount({this.title, this.rightView, required this.onChange, super.key});  @override  State<NumberCount> createState() => _NumberCountState();}class _NumberCountState extends State<NumberCount> {  int counter = 1;  TextEditingController textController = TextEditingController(text: "1");  @override  Widget build(BuildContext context) {    return Container(      color: BGColor_white_255,      padding: const EdgeInsets.fromLTRB(18, 0, 0, 0.6),      margin: const EdgeInsets.fromLTRB(0, 0, 0, 0.6),      child: Row(        mainAxisAlignment: MainAxisAlignment.start,        children: [          Text(widget.title??"", style: blackStyle()),          IconButton(            icon: const Icon(Icons.remove, size: 22, color: Colors.grey),            onPressed: () {              FocusScope.of(context).requestFocus(FocusNode());              if (counter == 1) return;              counter--;              textController.text = counter.toString();              widget.onChange(counter);            },          ),          SizedBox(            width: 60,            height: 32,            child: TextField(              controller: textController,              keyboardType: TextInputType.number,              cursorWidth: 2, // 设置光标宽度              cursorHeight: 14, // 设置光标高度              textAlign: TextAlign.center,              decoration: const InputDecoration(                filled: true,                fillColor: Colors.black12, // 设置背景色为红色                border: OutlineInputBorder(                  borderRadius: BorderRadius.all(Radius.circular(4)), // 设置圆角为6                  borderSide: BorderSide.none, // 移除默认边框                ),                contentPadding: EdgeInsets.zero,              ),              onChanged: (value) => counter = int.parse(value),            ),          ),          IconButton(            icon: const Icon(Icons.add, size: 22, color: Colors.grey),            onPressed: () {              FocusScope.of(context).requestFocus(FocusNode());              counter++;              textController.text = counter.toString();              widget.onChange(counter);            },          ), // const SizedBox(width: 50),          if (widget.rightView != null) widget.rightView!        ],      ),    );  }}